<!--vbase-->
<template>
  <q-card class="settings-script-editor">
    <q-card-actions align="right">
      <q-btn
        color="primary"
        class="q-mr-sm"
        @click="saveRecord"
        :label="$t('save')"
      />
    </q-card-actions>

    <q-card-section class="row items-center q-pb-none">
      <editor v-bind="{} as any"></editor
    ></q-card-section>

    <q-card-section
      class="row items-center q-pb-none full-width"
      style="min-height: 100px"
      v-if="display_output_view"
    >
      <div class="col-1">Result:</div>
      <pre class="col-11 bg-grey-3 script-output">{{ script_output }}</pre>
    </q-card-section>

    <q-inner-loading :showing="processing">
      <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
    </q-inner-loading>
  </q-card>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useDocScriptStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import editor from 'src/components/document/script/editor.vue';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  el: '#app',
    props: {},
  components: {
    editor,
  },
  watch: {
    selected_doc_type: {
      handler: function (newVal, oldVal) {
        this.initView();
      },
    },
  },
  data() {
    return {};
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    async initView() {
      try {
        if (!this.selected_doc_type) {
          logInfo('selected_doc_type is missing');
          return;
        }

        this.setEmptyModel();
        this.processing = true;
        await this.getScript();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
    async saveRecord() {
      try {
        this.processing = true;
        await this.saveCurrentModel();
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
  },
  setup() {
    const doc_script = useDocScriptStore();
    const { getScript, saveCurrentModel, setEmptyModel } = doc_script;
    const {
      current_model,
      selected_doc_type,
      display_output_view,
      script_output,
      processing,
      is_script_editor_available,
    } = storeToRefs(doc_script);

    return {
      is_script_editor_available,
      script_output,
      display_output_view,
      selected_doc_type,
      setEmptyModel,
      saveCurrentModel,
      getScript,
      current_model,
      processing,
      CalHeight: ref('600'),
    };
  },
});
</script>

<style lang="scss" scoped></style>

<style lang="scss">
.script-output {
  width: 986px;
  min-height: 100px;
  border: 1px solid #9e9e9e;
}
.settings-script-editor {
  margin-top: 10px;
}
</style>
