<!--vbase-->
<template>
  <div class="container p-b-0 q-pb-sm settings mt-mb-8">
    <template v-if="load_script">
      <settingsEditor />
    </template>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { useDocScriptStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import settingsEditor from 'src/components/document/script/settings-editor.vue';

export default defineComponent({
  el: '#app',
  mixins: [],
  props: {},
  components: {
    settingsEditor,
  },
  data() {
    return {};
  },
  mounted: function () {
    this.initView();
  },
  methods: {
    initView() {
      this.load_script = false;
      this.selected_doc_type = String(this.$route.params.type || '');
      this.load_script = true;
    },
  },
  setup() {
    const doc_script = useDocScriptStore();
    const { selected_doc_type } = storeToRefs(doc_script);

    return {
      selected_doc_type,
      load_script: ref(false),
    };
  },
});
</script>

<style lang="scss" scoped></style>
